444	/*
445	 * Returns true if the input it checked (if it checked anything) is not
446	 * encoded. A return of false indicates there's a percent at \a input that
447	 * needs to be decoded.
448	 */
449	#ifdef __SSE2__
450	static bool simdCheckNonEncoded(QChar *&output, const char16_t *&input, const char16_t *end)
451	{
452	#  ifdef __AVX2__
453	    const __m256i percents256 = _mm256_broadcastw_epi16(_mm_cvtsi32_si128('%'));
454	    const __m128i percents = _mm256_castsi256_si128(percents256);
455	#  else
456	    const __m128i percents = _mm_set1_epi16('%');
457	#  endif
458	
459	    uint idx = 0;
460	    quint32 mask = 0;
461	    if (input + 16 <= end) {
462	        qptrdiff offset = 0;
463	        for ( ; input + offset + 16 <= end; offset += 16) {
464	#  ifdef __AVX2__
465	            // do 32 bytes at a time using AVX2
466	            __m256i data = _mm256_loadu_si256(reinterpret_cast<const __m256i *>(input + offset));
467	            __m256i comparison = _mm256_cmpeq_epi16(data, percents256);
468	            mask = _mm256_movemask_epi8(comparison);
469	            _mm256_storeu_si256(reinterpret_cast<__m256i *>(output + offset), data);
470	#  else
471	            // do 32 bytes at a time using unrolled SSE2
472	            __m128i data1 = _mm_loadu_si128(reinterpret_cast<const __m128i *>(input + offset));
473	            __m128i data2 = _mm_loadu_si128(reinterpret_cast<const __m128i *>(input + offset + 8));
474	            __m128i comparison1 = _mm_cmpeq_epi16(data1, percents);
475	            __m128i comparison2 = _mm_cmpeq_epi16(data2, percents);
476	            uint mask1 = _mm_movemask_epi8(comparison1);
477	            uint mask2 = _mm_movemask_epi8(comparison2);
478	
479	            _mm_storeu_si128(reinterpret_cast<__m128i *>(output + offset), data1);
480	            if (!mask1)
481	                _mm_storeu_si128(reinterpret_cast<__m128i *>(output + offset + 8), data2);
482	            mask = mask1 | (mask2 << 16);
483	#  endif
484	
485	            if (mask) {
486	                idx = qCountTrailingZeroBits(mask) / 2;
487	                break;
488	            }
489	        }
490	
491	        input += offset;
492	        if (output)
493	            output += offset;
494	    } else if (input + 8 <= end) {
495	        // do 16 bytes at a time
496	        __m128i data = _mm_loadu_si128(reinterpret_cast<const __m128i *>(input));
497	        __m128i comparison = _mm_cmpeq_epi16(data, percents);
498	        mask = _mm_movemask_epi8(comparison);
499	        _mm_storeu_si128(reinterpret_cast<__m128i *>(output), data);
500	        idx = qCountTrailingZeroBits(quint16(mask)) / 2;
501	    } else if (input + 4 <= end) {
502	        // do 8 bytes only
503	        __m128i data = _mm_loadl_epi64(reinterpret_cast<const __m128i *>(input));
504	        __m128i comparison = _mm_cmpeq_epi16(data, percents);
505	        mask = _mm_movemask_epi8(comparison) & 0xffu;
